def is_samepatterns(sequences, patterns):
    if len(sequences) != len(patterns):
        return False

    seq_to_pat = {}
    pat_to_seq = {}
    for s, p in zip(sequences, patterns):
        if s in seq_to_pat:
            if seq_to_pat[s] != p:
                return False
        else:
            seq_to_pat[s] = p

        if p in pat_to_seq:
            if pat_to_seq[p] != s:
                return False
        else:
            pat_to_seq[p] = s

    return True
